    };
    let (_, json) = crate::camera_profiles::BUNDLED.iter().find(|(m, _)| *m == "ILCE-7CR").expect("ILCE-7CR is built in");
    let bundled: crate::camera_profiles::CameraProfile = serde_json::from_str(json).unwrap();
