cmd!(
    "album.addPhotos",
    "Add to Album",
    ["Photo"],
    None,
    "{id: albumId, ids?: [photoIds]} (default: selection) → {added, skipped}; Local photos are skipped (albums hold library photos), only Local ones is an error",
    has_library_selection,
    |s, p| {
        let id = album_param(p, "id", "album.addPhotos")?;
